<body>

<div id="claim-form">
  <h1>Disability Claim Submission</h1>
  <label for="policy-number">Policy Number:</label>
  <input type="text" id="policy-number">

  <label for="member-id">Member ID:</label>
  <input type="text" id="member-id">
  <button type="button" onclick="lookupMember()">Look up member</button>

  <div id="member-details"></div>

  <label for="last-day-worked">Last Day Worked:</label>
  <input type="date" id="last-day-worked">

  <label for="first-day-absent">First Day Absent:</label>
  <input type="date" id="first-day-absent">

  <label for="nature-of-absence">Nature of Absence:</label>
  <select id="nature-of-absence">
    <option value="illness">Illness</option>
    <option value="injury">Injury</option>
    <option value="other">Other</option>
  </select>

  <label for="details">Details:</label>
  <textarea id="details"></textarea>

  <label for="documents">Document Upload:</label>
  <input type="file" id="documents" multiple onchange="updateFileList()">
  <ul id="file-list"></ul>

  <button type="button" onclick="submitForm()">Submit</button>
</div>

<div id="confirmation">
  <h2>Submission Received</h2>
  <p>Reference Number: <span id="reference-number"></span></p>
  <p>Status: Received</p>
</div>

<p id="footer-note">MapleSure Insurance — fictional demo application</p>

<script>
  // Mock data for member lookup
  const mockData = {
    "12345": "John Doe",
    "67890": "Jane Smith"
  };

  // Lookup member function
  function lookupMember() {
    const memberId = document.getElementById('member-id').value;
    const memberDetails = document.getElementById('member-details');
    if (mockData[memberId]) {
      memberDetails.innerHTML = `<strong>Member Name:</strong> ${mockData[memberId]}`;
    } else {
      memberDetails.innerHTML = "<strong>Member not found.</strong>";
    }
  }

  // Update file list function
  function updateFileList() {
    const input = document.getElementById('documents');
    const fileList = document.getElementById('file-list');
    fileList.innerHTML = '';
    for (let i = 0; i < input.files.length; i++) {
      const li = document.createElement('li');
      li.textContent = input.files[i].name;
      fileList.appendChild(li);
    }
  }

  // Submit form function
  function submitForm() {
    const form = document.getElementById('claim-form');
    const confirmation = document.getElementById('confirmation');
    form.style.display = 'none';
    confirmation.style.display = 'block';
    const referenceNumber = `MS-2026-08-${Math.floor(1000 + Math.random() * 9000)}`;
    document.getElementById('reference-number').textContent = referenceNumber;
    trackAnalyticsEvent('Form Submitted');
  }

  // Analytics tracking function
  function trackAnalyticsEvent(eventType) {
    console.log(`Analytics Event: ${eventType}`);
    // The eventType is recorded in the analytics system without personal data.
  }

  // Track page view when the script loads
  trackAnalyticsEvent('Page Viewed');

  // Add event listener for call-to-action click
  document.getElementById('claim-form').addEventListener('click', function(event) {
    if (event.target.tagName === 'BUTTON') {
      trackAnalyticsEvent('Call to Action Clicked');
    }
  });
</script>

</body>
</html>


